  const rad=state.heading*Math.PI/180,speedM=state.ias*.5144;state.x+=Math.sin(rad)*speedM*dt;state.z-=Math.cos(rad)*speedM*dt;state.flightSeconds+=dt;saved.hours+=dt/3600;if(Math.floor(state.flightSeconds)%30===0)localStorage.setItem('b738-sim-records',JSON.stringify(saved));aircraft.position.set(state.x,state.y,state.z);aircraft.rotation.order='YXZ';aircraft.rotation.set(state.pitch*Math.PI/180,-rad,state.roll*-Math.PI/180);
  if(state.onGround&&!onAirportPavement(state.x,state.z)){state.ias=Math.max(0,state.ias-7*dt);state.offPavementTime=state.ias>55?state.offPavementTime+dt:Math.max(0,state.offPavementTime-dt*2)}else state.offPavementTime=0;if(state.offPavementTime>2.2)crash('高速驶出机场铺装面，飞行结束');for(const o of obstacles)if(state.y<800&&Math.hypot(state.x-o.x,state.z-o.z)<o.r)crash(`撞上${o.type}，飞行结束`);
